package main

import (
	"context"
	"errors"
	"fmt"
	"log"
	"os"
	"strings"
	"time"

	"github.com/aws/aws-sdk-go-v2/aws"
	"github.com/aws/aws-sdk-go-v2/config"
	"github.com/aws/aws-sdk-go-v2/credentials"
	"github.com/aws/aws-sdk-go-v2/service/s3"
	"github.com/pocketbase/pocketbase"
	"github.com/pocketbase/pocketbase/core"
)

func main() {
	app := pocketbase.New()

	app.OnBeforeServe().BindFunc(func(se *core.ServeEvent) error {
		se.Router.GET("/api/s3-presign", func(e *core.RequestEvent) error {
			filename := e.Request.URL.Query().Get("filename")
			if strings.TrimSpace(filename) == "" {
				return e.BadRequest(400, errors.New("filename query parameter is required"))
			}

			region := os.Getenv("AWS_REGION")
			accessKey := os.Getenv("AWS_ACCESS_KEY_ID")
			secretKey := os.Getenv("AWS_SECRET_ACCESS_KEY")
			bucket := os.Getenv("AWS_BUCKET")

			if region == "" || accessKey == "" || secretKey == "" || bucket == "" {
				return e.InternalServerError(500, errors.New("missing AWS configuration environment variables"))
			}

			runIDBytes, err := os.ReadFile("/logs/artifacts/run-id")
			if err != nil {
				return e.InternalServerError(500, fmt.Errorf("failed to read run-id: %w", err))
			}
			runID := strings.TrimSpace(string(runIDBytes))

			key := fmt.Sprintf("uploads/%s/%s", runID, filename)

			cfg, err := config.LoadDefaultConfig(context.Background(),
				config.WithRegion(region),
				config.WithCredentialsProvider(credentials.NewStaticCredentialsProvider(accessKey, secretKey, "")),
			)
			if err != nil {
				return e.InternalServerError(500, fmt.Errorf("failed to load AWS config: %w", err))
			}

			client := s3.NewFromConfig(cfg)

			presignClient := s3.NewPresignClient(client)

			request, err := presignClient.PresignPutObject(context.Background(), &s3.PutObjectInput{
				Bucket: aws.String(bucket),
				Key:    aws.String(key),
			}, s3.WithPresignExpires(15*time.Minute))
			if err != nil {
				return e.InternalServerError(500, fmt.Errorf("failed to presign URL: %w", err))
			}

			return e.JSON(200, map[string]string{"url": request.URL})
		})

		return se.Next()
	})

	if err := app.Start(); err != nil {
		log.Fatal(err)
	}
}
EOF
